function safeParseEuro(str){
  const n = Number.parseFloat(String(str));
  return Number.isFinite(n) ? n : 0;
}
exports.safeParseEuro = safeParseEuro;

function formatPercent(x){
  return new Intl.NumberFormat('en-US',{style:'percent',maximumFractionDigits:1}).format(Number(x));
}
exports.formatPercent = formatPercent;
